interface Row {
  m: string; id: string; name: string; sub: string; rooms: string[]; style: string; desc: string; tags: string[];
  tier: PriceTier; price: number; q: number; fp: 'FP11' | 'FP21' | 'FP12' | 'FP22'; stats: ObjectStats;
  /** Seat-top or mattress-top height (metres). */
  y: number; slots: SlotSpec[]; packs?: string[]; inter?: string[]; open?: Array<[number, number]>;
  /** Put the model's back against the wall edge (beds, sofas, sectionals). */
  wall?: boolean;
}

