export default function build(k: ObjectKit): ObjectDef[] {
  const { fit, obj, sit, sleep, region, sw, woodR, metalR, darkMetalR, FABRIC, FABRIC_BLUE, FABRIC_BRICK, METAL_MEDIUM, APPLIANCE, WOOD, FP11, FP21, FP12, FP22, WALL_GAP, r3, dollars } = k;
  const FPS = { FP11, FP21, FP12, FP22 };
  const CREAM = [sw('cream', 'Cream', '#f8ffff'), ...FABRIC.slice(1)];

  /** Finish regions from the materials a model really has: fabric (biggest first), wood, then metals. */
  const finishes = (mats: string[], seat: boolean): FinishRegion[] => {
    const out: FinishRegion[] = [];
    const labels = seat ? ['Upholstery', 'Cushions', 'Trim', 'Piping'] : ['Bedding', 'Sheets', 'Trim', 'Accent'];
    const swatches: Record<string, ReturnType<typeof sw>[]> = { carpet: FABRIC, carpetBlue: FABRIC_BLUE, carpetWhite: CREAM, carpetDarker: FABRIC_BRICK };
    mats.filter((m) => m in swatches).forEach((m, i) => out.push(region(i === 0 ? 'fabric' : `fabric${i + 1}`, labels[i] ?? 'Trim', [m], swatches[m]!)));
    if (mats.includes('wood')) out.push(woodR(mats.includes('woodDark') ? ['wood', 'woodDark'] : ['wood']));
    else if (mats.includes('woodDark')) out.push(region('wood', 'Wood', ['woodDark'], [sw('warm-brown', 'Warm Brown', '#ad754c'), ...WOOD]));
    if (mats.includes('metal')) out.push(metalR(['metal']));
    if (mats.includes('metalDark')) out.push(mats.includes('metal') ? region('metalDark', 'Dark Metal', ['metalDark'], k.METAL_DARK) : darkMetalR('Metal'));
    if (mats.includes('metalMedium')) out.push(region('metalMedium', 'Frame', ['metalMedium'], METAL_MEDIUM));
    if (mats.includes('metalLight')) out.push(region('metalLight', 'Pedestal', ['metalLight'], APPLIANCE));
    return out;
  };

  return ROWS.map((r) => {
    const fp = FPS[r.fp];
    const f = fit(r.m, fp, 2, r.wall ? { back: WALL_GAP } : {});
    const bed = r.tags.includes(BED);
    const slots: ObjectSlot[] = r.slots.map(([id, x, z, approach, facing, height]) => {
      const pos: [number, number] = [r3(x + f.model.offset[0]), r3(z + f.model.offset[2])];
      return (bed ? sleep : sit)(id, pos, height ?? r.y, approach, ...(bed ? [] : [facing ?? 0]) as [number?]);
    });
    return obj(f, {
      id: r.id, name: r.name, category: bed ? 'beds' : 'seating', subcategory: r.sub, rooms: r.rooms, style: r.style, description: r.desc,
      tags: r.tags, ...(r.packs ? { packs: r.packs } : {}), tier: r.tier, price: dollars(r.price), quality: r.q, functional: true,
      footprint: fp, layer: 'floor', blocksMovement: true, ...(r.open ? { openCells: r.open } : {}),
      slots, interactions: r.inter ?? (bed ? ['sleep', 'nap'] : ['sit']), stats: r.stats, finishes: finishes(MATS[r.m] ?? [], !bed),
    });
  });
}
